/* GENESIS frontend logic.
 *
 * Data source: frontend/data.json, generated from the real engine by
 *   python frontend/generate_data.py   (seed 42, 100 days)
 * Every number on this page comes from that file. EMBEDDED_DATA (in
 * data.js, generated by the same script) is a snapshot of the same file,
 * used only when data.json cannot be fetched (e.g. the page was opened
 * directly via file://). Never hand-edit either file — regenerate them.
 */
"use strict";


const OCC_COLORS = { farmer: "#4f46e5", woodcutter: "#64748b", miner: "#1e293b" };
const STAGE_COLORS = { farmer: "#8b85f5", woodcutter: "#94a3b8", miner: "#e2e8f0" };
const OCC_NAMES = { farmer: "农民 farmer", woodcutter: "伐木工 woodcutter", miner: "矿工 miner" };
const RES_META = {
  food: { icon: "粮", name: "食物", en: "FOOD" },
  wood: { icon: "木", name: "木材", en: "WOOD" },
  stone: { icon: "石", name: "石头", en: "STONE" },
};

let DATA = null;
let selectedDay = 100;
let showAllResidents = false;
let playTimer = null;

const $ = (id) => document.getElementById(id);
const fmt = (n) => Number(n).toLocaleString("en-US");
const money = (n) => fmt(Number(n).toFixed(2));

function loadData() {
  return fetch("data.json")
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error("no data.json"))))
    .catch(() => {
      if (typeof EMBEDDED_DATA !== "undefined" && EMBEDDED_DATA) return EMBEDDED_DATA;
      throw new Error("no demo data available");
    });
}

function renderHero(d) {
  $("hs-day").textContent = d.final.day;
  $("hs-pop").textContent = d.final.population;
  $("hs-trades").textContent = fmt(d.final.total_trades);
  $("hs-digest").textContent = d.meta.digest;
}

function renderKpis(d) {
  const f = d.final;
  const w = f.wealth;
  const cards = [
    { num: `${f.day}`, label: "天 · 种子 42", sub: "20 位居民，一个世界" },
    { num: `${f.population}<small> / 20</small>`, label: "存活人口", sub: `${f.dead} 人死亡 · 健康 ${f.mean_health}` },
    { num: `${fmt(f.money_supply)}`, label: "货币供给 credits", sub: "恒定不变 · 账目永远平衡" },
    { num: `${fmt(f.total_trades)}`, label: "累计交易", sub: `${fmt(f.total_units)} 单位 · ${money(f.total_value)} credits` },
    { num: `${fmt(f.events)}`, label: "事件日志", sub: "每笔账都有记录，可审计" },
    { num: `${w.gini}`, label: "基尼系数 Gini", sub: "第 10 天 0.057 → 第 100 天 0.308" },
    { num: `${money(w.mean)}`, label: "人均财富 credits", sub: `中位 ${money(w.median)} · 最高 ${money(w.max)}` },
    { num: `${w.richest_10_pct}%`, label: "最富 10% 占有财富", sub: `最穷 50% 占有 ${w.poorest_50_pct}%` },
  ];
  $("kpi-grid").innerHTML = cards
    .map((c) => `<div class="kpi"><div class="kpi-num">${c.num}</div><div class="kpi-label">${c.label}</div><div class="kpi-sub">${c.sub}</div></div>`)
    .join("");
}

function trajectoryPoint(day) {
  return DATA.trajectory.find((t) => t.day === day) || DATA.trajectory[DATA.trajectory.length - 1];
}

function renderSim(day) {
  selectedDay = day;
  const t = trajectoryPoint(day);
  document.querySelectorAll(".chip").forEach((c) => c.classList.toggle("active", Number(c.dataset.day) === day));
  $("sim-day-num").textContent = t.day;
  const sd = $("stage-day");
  if (sd) sd.textContent = t.day;
  const rows = [
    ["当日交易", `${t.trades} 笔`],
    ["交易单位", `${t.units} 单位`],
    ["当日成交额", `${money(t.value)} credits`],
    ["平均健康", `${t.health.toFixed(1)}`],
    ["基尼系数", `${t.gini.toFixed(3)}`],
    ["人口", `${t.population} 人`],
  ];
  $("sim-rows").innerHTML = rows.map(([k, v]) => `<div class="sim-row"><span>${k}</span><b>${v}</b></div>`).join("");
  drawChart();
}

function drawChart() {
  const canvas = $("gini-chart");
  if (!canvas || !canvas.getContext) return;
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height, padL = 44, padR = 34, padT = 18, padB = 30;
  ctx.clearRect(0, 0, W, H);
  const pts = DATA.trajectory;
  const maxG = 0.35;
  const x = (day) => padL + ((day - 10) / 90) * (W - padL - padR);
  const y = (g) => H - padB - (g / maxG) * (H - padT - padB);
  // gridlines
  ctx.strokeStyle = "#e5e7eb";
  ctx.fillStyle = "#9ca3af";
  ctx.font = "11px ui-monospace, monospace";
  ctx.textAlign = "right";
  [0, 0.1, 0.2, 0.3].forEach((g) => {
    ctx.beginPath(); ctx.moveTo(padL, y(g)); ctx.lineTo(W - padR, y(g)); ctx.stroke();
    ctx.fillText(g.toFixed(1), padL - 8, y(g) + 4);
  });
  // area fill
  const grad = ctx.createLinearGradient(0, padT, 0, H - padB);
  grad.addColorStop(0, "rgba(79,70,229,0.18)");
  grad.addColorStop(1, "rgba(79,70,229,0.01)");
  ctx.beginPath();
  pts.forEach((p, i) => (i === 0 ? ctx.moveTo(x(p.day), y(p.gini)) : ctx.lineTo(x(p.day), y(p.gini))));
  ctx.lineTo(x(100), H - padB); ctx.lineTo(x(10), H - padB); ctx.closePath();
  ctx.fillStyle = grad; ctx.fill();
  // line
  ctx.beginPath();
  pts.forEach((p, i) => (i === 0 ? ctx.moveTo(x(p.day), y(p.gini)) : ctx.lineTo(x(p.day), y(p.gini))));
  ctx.strokeStyle = "#4f46e5"; ctx.lineWidth = 2.5; ctx.stroke();
  // points
  pts.forEach((p) => {
    const sel = p.day === selectedDay;
    ctx.beginPath(); ctx.arc(x(p.day), y(p.gini), sel ? 6 : 3.5, 0, Math.PI * 2);
    ctx.fillStyle = sel ? "#111827" : "#4f46e5"; ctx.fill();
    if (sel) { ctx.strokeStyle = "#fff"; ctx.lineWidth = 1.5; ctx.stroke(); }
  });
  // x labels
  ctx.fillStyle = "#9ca3af"; ctx.textAlign = "center";
  pts.forEach((p) => ctx.fillText(`D${p.day}`, x(p.day), H - 10));
}

function renderMarket(d) {
  const f = d.final;
  const maxPrice = Math.max(...Object.values(f.prices));
  $("market-grid").innerHTML = Object.keys(RES_META).map((res) => {
    const m = RES_META[res];
    const pct = Math.round((f.prices[res] / maxPrice) * 100);
    const barClass = res === "food" ? "bar-food" : res === "wood" ? "bar-wood" : "bar-stone";
    return `<div class="market-row">
      <div class="res-icon">${m.icon}</div>
      <div><h3>${m.name}</h3><div class="res-en">${m.en}</div></div>
      <div class="price">${f.prices[res].toFixed(2)}<small> credits / 单位</small></div>
      <div>
        <div class="bar-track"><div class="bar-fill ${barClass}" style="width:${pct}%"></div></div>
        <div class="res-stats" style="margin-top:10px">
          <div><span>持有</span><b>${fmt(f.holdings[res])}</b></div>
          <div><span>累计生产</span><b>${fmt(f.produced[res])}</b></div>
          <div><span>累计消费</span><b>${fmt(f.consumed[res])}</b></div>
        </div>
      </div>
    </div>`;
  }).join("");
  $("market-foot").textContent =
    `100 天累计：${fmt(f.total_trades)} 笔交易 · ${fmt(f.total_units)} 单位 · ${money(f.total_value)} credits。` +
    `生产：食物 ${fmt(f.produced.food)} / 木材 ${fmt(f.produced.wood)} / 石头 ${fmt(f.produced.stone)}；` +
    `消费：食物 ${fmt(f.consumed.food)} / 木材 ${fmt(f.consumed.wood)} / 石头 ${fmt(f.consumed.stone)}。` +
    `货币供给恒定 ${fmt(f.money_supply)} credits —— 没有凭空印钱，也没有钱消失。`;
}

function renderResidents(d) {
  const f = d.final;
  const occ = f.occupations;
  const total = Object.values(occ).reduce((a, b) => a + b, 0);
  // donut via conic-gradient
  let acc = 0;
  const stops = Object.keys(occ).map((k) => {
    const start = (acc / total) * 360; acc += occ[k];
    const end = (acc / total) * 360;
    return `${OCC_COLORS[k]} ${start}deg ${end}deg`;
  }).join(", ");
  $("donut").style.background = `conic-gradient(${stops})`;
  $("donut-total").textContent = total;
  $("occ-legend").innerHTML = Object.keys(occ).map((k) =>
    `<li><span class="swatch" style="background:${OCC_COLORS[k]}"></span>${OCC_NAMES[k]}<b>${occ[k]} 人</b></li>`).join("");
  const w = f.wealth;
  $("wealth-stats").innerHTML = [
    [`${money(w.mean)}`, "平均财富"],
    [`${money(w.median)}`, "中位财富"],
    [`${money(w.min)}`, "最穷"],
    [`${money(w.max)}`, "最富"],
  ].map(([b, s]) => `<div class="ws"><b>${b}</b><span>${s}</span></div>`).join("");
  renderResidentTable(d);
}

function renderResidentTable(d) {
  const rows = showAllResidents ? d.residents : d.residents.slice(0, 8);
  $("resident-table").querySelector("tbody").innerHTML = rows.map((r, i) => {
    const rank = d.residents.indexOf(r) + 1;
    return `<tr class="${rank <= 3 ? "top3" : ""}">
      <td>${rank}</td><td>${r.name}</td><td>${OCC_NAMES[r.occupation].split(" ")[0]}</td>
      <td class="num">${r.health}</td><td class="num">${money(r.cash)}</td><td class="num">${money(r.wealth)}</td>
    </tr>`;
  }).join("");
  $("btn-more-residents").textContent = showAllResidents ? "收起" : "展开全部 20 人";
}

function renderAnchor(d) {
  $("digest-full").textContent = d.meta.full_digest;
}

function buildChips(d) {
  $("day-chips").innerHTML = d.trajectory.map((t) =>
    `<button class="chip${t.day === selectedDay ? " active" : ""}" data-day="${t.day}">Day ${t.day}</button>`).join("");
  document.querySelectorAll(".chip").forEach((c) =>
    c.addEventListener("click", () => { stopPlay(); renderSim(Number(c.dataset.day)); }));
}

function play() {
  if (playTimer) { stopPlay(); return; }
  $("btn-play").textContent = "暂停";
  $("hero-play").textContent = "暂停回放";
  let i = DATA.trajectory.findIndex((t) => t.day === selectedDay);
  playTimer = setInterval(() => {
    i = (i + 1) % DATA.trajectory.length;
    renderSim(DATA.trajectory[i].day);
    if (i === DATA.trajectory.length - 1) stopPlay();
  }, 900);
}

function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  $("btn-play").textContent = "播放";
  $("hero-play").textContent = "▶ 播放模拟";
}

/* ---------- world stage: autonomous, never follows the mouse ----------
 * 20 resident nodes drift on slow orbits + dust motes + a Gini trace
 * that cycles Day 10 -> 100. No mousemove listener anywhere on purpose.
 * dt is clamped so a slow frame slows the world instead of jumping it.
 */
const stageNodes = [];
const stageMotes = [];
let stageVisible = true;
let stageT0 = null;

function initStage(d) {
  const canvas = $("world-stage");
  if (!canvas || !canvas.getContext) return;
  // deterministic layout: same seed, same world — positions from index only
  d.residents.forEach((r, i) => {
    const a = (i / d.residents.length) * Math.PI * 2;
    const rr = 0.20 + ((i * 37) % 10) / 10 * 0.22; // 0.20..0.42 of min dimension
    stageNodes.push({
      occ: r.occupation, baseA: a, r: rr,
      speed: 0.05 + ((i * 13) % 7) * 0.012,
      phase: i * 1.7, size: 3 + ((i * 11) % 3),
    });
  });
  for (let i = 0; i < 36; i++) {
    stageMotes.push({
      x: ((i * 97) % 100) / 100, y: ((i * 61) % 100) / 100,
      vx: 0.002 + ((i * 7) % 5) * 0.001, vy: -0.001 - ((i * 3) % 4) * 0.0006,
      s: 0.8 + ((i * 5) % 3) * 0.6, tw: i * 0.9,
    });
  }
  const stage = $("stage");
  if ("IntersectionObserver" in window && stage) {
    new IntersectionObserver((es) => { stageVisible = es[0].isIntersecting; }).observe(stage);
  }
  requestAnimationFrame(drawStage);
}

function drawStage(now) {
  const canvas = $("world-stage");
  if (!canvas) return;
  // reduced motion: one static frame, no loop — the world stands still
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    drawStageFrame(canvas, 12000, 0);
    return;
  }
  requestAnimationFrame(drawStage);
  if (document.hidden || !stageVisible) { stageT0 = now; return; }
  if (stageT0 === null) stageT0 = now;
  const dt = Math.min(0.1, (now - stageT0) / 1000);
  stageT0 = now;
  drawStageFrame(canvas, now, dt);
}

function drawStageFrame(canvas, now, dt) {
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height;
  const t = now / 1000;
  ctx.clearRect(0, 0, W, H);
  // faint grid
  ctx.strokeStyle = "rgba(255,255,255,0.045)";
  ctx.lineWidth = 1;
  for (let gx = 0; gx <= W; gx += 44) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, H); ctx.stroke(); }
  for (let gy = 0; gy <= H; gy += 44) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke(); }
  const cx = W * 0.5, cy = H * 0.42, R = Math.min(W, H) * 0.62;
  // slow autonomous camera drift: the whole field breathes
  const driftX = Math.sin(t * 0.07) * 10, driftY = Math.cos(t * 0.05) * 8;
  // orbit ring
  ctx.beginPath(); ctx.arc(cx + driftX, cy + driftY, R * 0.42, 0, Math.PI * 2);
  ctx.strokeStyle = "rgba(255,255,255,0.10)"; ctx.stroke();
  // resident nodes on slow orbits
  stageNodes.forEach((n) => {
    const a = n.baseA + t * n.speed;
    const x = cx + driftX + Math.cos(a) * R * n.r;
    const y = cy + driftY + Math.sin(a) * R * n.r * 0.62 + Math.sin(t * 0.4 + n.phase) * 4;
    ctx.beginPath(); ctx.arc(x, y, n.size, 0, Math.PI * 2);
    ctx.fillStyle = STAGE_COLORS[n.occ]; ctx.globalAlpha = 0.9; ctx.fill(); ctx.globalAlpha = 1;
  });
  // dust motes: drift up, wrap round the eye
  stageMotes.forEach((m) => {
    m.x += m.vx * dt; m.y += m.vy * dt;
    if (m.y < -0.02) m.y = 1.02;
    if (m.x > 1.02) m.x = -0.02;
    ctx.beginPath(); ctx.arc(m.x * W, m.y * H, m.s, 0, Math.PI * 2);
    ctx.fillStyle = "rgba(232,234,242," + (0.12 + 0.1 * Math.sin(t * 0.8 + m.tw)) + ")";
    ctx.fill();
  });
  // Gini trace along the bottom, cycling Day 10 -> 100 on its own.
  // Kept above the stats overlay (which starts ~142 canvas px from bottom).
  const pts = DATA.trajectory;
  const padL = 48, padR = 48, baseY = H - 172, topY = H - 252;
  const cycle = (t % 18) / 18; // 18s full sweep
  const upto = Math.max(1, Math.floor(cycle * pts.length));
  ctx.beginPath();
  pts.slice(0, upto + 1).forEach((p, i) => {
    const x = padL + ((p.day - 10) / 90) * (W - padL - padR);
    const y = baseY - (p.gini / 0.35) * (baseY - topY);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  });
  ctx.strokeStyle = "#5b55e8"; ctx.lineWidth = 2; ctx.stroke();
  const last = pts[Math.min(upto, pts.length - 1)];
  const lx = padL + ((last.day - 10) / 90) * (W - padL - padR);
  const ly = baseY - (last.gini / 0.35) * (baseY - topY);
  ctx.beginPath(); ctx.arc(lx, ly, 4.5, 0, Math.PI * 2);
  ctx.fillStyle = "#e8eaf2"; ctx.fill();
  ctx.fillStyle = "#8290a5"; ctx.font = "11px ui-monospace, monospace"; ctx.textAlign = "left";
  ctx.fillText("GINI  Day " + last.day + "  ·  " + last.gini.toFixed(3), padL, H - 152);
}

/* ---------- scroll: cue fades, back-to-top fades in late, sections glide ---------- */
function initScroll() {
  const cue = $("cue");
  const topBtn = $("top-btn");
  const onScroll = () => {
    const y = window.scrollY || 0;
    if (cue) cue.classList.toggle("away", y > 40);
    if (topBtn) topBtn.classList.toggle("on", y > window.innerHeight * 0.8);
  };
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();
  if (topBtn) topBtn.addEventListener("click", () => {
    const rm = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    window.scrollTo({ top: 0, behavior: rm ? "auto" : "smooth" });
  });
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver((es) => {
      es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } });
    }, { threshold: 0.05, rootMargin: "0px 0px 200px 0px" });
    document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
  } else {
    document.querySelectorAll(".reveal").forEach((el) => el.classList.add("in"));
  }
}

document.addEventListener("DOMContentLoaded", () => {
  loadData().then((data) => {
    DATA = data;
    renderHero(data);
    renderKpis(data);
    buildChips(data);
    renderSim(100);
    renderMarket(data);
    renderResidents(data);
    renderAnchor(data);
    initStage(data);
    initScroll();
    // intro: glitch flash (~1.5s) + stage fade (2.4s) — then settle to visible
    setTimeout(() => document.body.classList.remove("loading"), 4200);
    $("btn-play").addEventListener("click", play);
    $("hero-play").addEventListener("click", () => { renderSim(10); play(); });
    $("btn-more-residents").addEventListener("click", () => {
      showAllResidents = !showAllResidents;
      renderResidentTable(DATA);
    });
    $("btn-copy").addEventListener("click", () => {
      const text = $("digest-full").textContent;
      if (navigator.clipboard) navigator.clipboard.writeText(text).then(() => {
        $("btn-copy").textContent = "已复制";
        setTimeout(() => { $("btn-copy").textContent = "复制摘要"; }, 1500);
      });
    });
    window.addEventListener("resize", drawChart);
  }).catch((err) => {
    document.querySelector("main").insertAdjacentHTML("afterbegin",
      `<div style="max-width:1160px;margin:20px auto;padding:16px 24px;background:#3f1d1d;border:1px solid #f87171;border-radius:12px;">数据加载失败：${err.message}。请用 python -m http.server 打开，或重新运行 python frontend/generate_data.py。</div>`);
  });
});
